        private static void SeedC91Preview(MainWindow window, string mode) { SequenceDocument sequence = GetField(window, "_sequenceDocument") as SequenceDocument; if (sequence == null) return; FctStudioProject project = C91SequenceProjectFactory.Create(sequence); FieldInfo projectField = window.GetType().GetField("_studioProject", BindingFlags.Instance | BindingFlags.NonPublic); if (projectField == null) return; projectField.SetValue(window, project); ComboBox productBox = GetField(window, "_productModelComboBox") as ComboBox; if (productBox != null) productBox.SelectedItem = productBox.Items.Cast<object>().OfType<ProductCanProfile>().FirstOrDefault(value => value.Model == ProductModel.C91); FunctionBlockStudioPanel blocks = GetField(window, "_functionBlockStudioPanel") as FunctionBlockStudioPanel; StudioFlowEditorPanel flow = GetField(window, "_studioFlowEditorPanel") as StudioFlowEditorPanel; TabControl tabs = GetField(window, "_mainTabs") as TabControl; object blockTab = GetField(window, "_functionBlockStudioTab"), flowTab = GetField(window, "_studioFlowTab"); if (blocks != null) blocks.RefreshProject(); if (flow != null) flow.RefreshProject(); if (mode == "c91-flow") ShowWorkspaceMode(window, false); else { ShowWorkspaceMode(window, true); int blockIndex = mode == "c91-block" ? 1 : 0; if (mode == "c91-main-test-limit") blockIndex = project.Blocks.FindIndex(block => block.Steps.Any(step => step.ToStep().FunctionName == "Test_UVW_Current_RMS")); if (blockIndex < 0) blockIndex = 0; if (blocks != null) blocks.SelectBlock(project.Blocks[blockIndex].Id); DataGrid stepList = blocks == null ? null : GetField(blocks, "_stepList") as DataGrid; if (stepList != null && mode == "c91-limit" && stepList.Items.Count > 11) stepList.SelectedIndex = 11; else if (stepList != null && mode == "c91-composite") stepList.SelectedIndex = 0; else if (stepList != null && mode == "c91-main-test-limit") { BlockStepDefinition resultStep = project.Blocks[blockIndex].Steps.First(step => step.T